    const idx = buildIndex([
      { id: 'z9', text: 'alpha beta' },
      { id: 'a1', text: 'alpha beta' }
    ])
    same(bm25Rank(idx, 'alpha').map((r) => r.id), ['a1', 'z9'])
  })
  check('topK 截断生效', () => {
    same(bm25Rank(index, 'vue reactivity', { k: 1 }).length, 1)
  })
}

